const resposta = $input.first().json;

if (!resposta.access_token) {
  throw new Error('Token não retornado pela API. Verifique App ID, App Secret e token atual.');
}

const token_novo = resposta.access_token;
const tipo = resposta.token_type || 'bearer';

const staticData = $getWorkflowStaticData('global');
staticData.ultimo_token = token_novo;
staticData.ultima_renovacao = new Date().toISOString();

return [{
  json: {
    token_novo,
    tipo,
    renovado_em: new Date().toLocaleString('pt-BR'),
    instrucao: 'Copie o token_novo e atualize na credencial Query Auth do nó 4 do workflow principal'
  }
}];

const token = $json.token_novo;
const data = $json.renovado_em;

console.log(`Token renovado com sucesso em ${data}`);
console.log(`Novo token: ${token}`);

return [{
  json: {
    status: 'SUCESSO',
    mensagem: `Token renovado em ${data}. Atualize manualmente na credencial do nó 4 do workflow principal.`,
    token_novo: token
  }
}];

console.error('Falha na renovação do token do Threads');

return [{
  json: {
    status: 'ERRO',
    mensagem: 'Token não foi renovado. Verifique App ID, App Secret e token atual no nó 2.',
    acao: 'Acesse developers.facebook.com, gere um novo token manualmente e atualize o nó 2 e a credencial do workflow principal.'
  }
}];
